  const handleAssignDefaultDriverToAllDays = async (driverId: string) => {
    if (!driverId) return;
    const driver = masterData.drivers?.find((d: any) => d.id === driverId);
    const baseRate = driver?.per_day_rate ? Number(driver.per_day_rate) : 15;
    const totalDays = touristData?.preferences?.duration_days || tripData?.profile?.durationDays || 5;

    const driverMarkupPercent = appSettings?.diver_markup !== undefined
      ? Number(appSettings.diver_markup)
      : (Number(appSettings?.[Settings.Driver_Markup]) || Number(appSettings?.driver_markup) || 0);
    const markupFactor = 1 + (driverMarkupPercent / 100);

    const nextAssignments: Record<number, TourDailyDriverDTO[]> = {};
    for (let day = 1; day <= totalDays; day++) {
      nextAssignments[day] = [
        {
          tour_id: tourId,
          day_number: day,
          driver_id: driverId,
          per_day_rate: baseRate,
          accommodation_cost: 0,
          meal_cost: 0,
          other_allowance: 0,
          contracted_per_day_rate: baseRate,
          contracted_accommodation_cost: 0,
          contracted_meal_cost: 0,
          contracted_other_allowance: 0,
          charged_per_day_rate: Math.round(baseRate * markupFactor * 100) / 100,
          charged_accommodation_cost: 0,
          charged_meal_cost: 0,
          charged_other_allowance: 0,
          notes: ''
        }
      ];
    }

    setDailyDriverAssignments(nextAssignments);

    setItinerary(prevItin => prevItin.map(block => {
      if (block.type === ItineraryBlockTypes.TRAVEL) {
        return { ...block, driverId };
      }
      return block;
    }));

    const payloads = Object.values(nextAssignments).flat();
    const res = await saveTourDailyDriversAction(tourId, payloads);
    if (!res.success) {
      console.error("Failed to save default driver assignments:", res.error);
    }
  };

  const handleUpdateDailyDriverField = (dayNum: number, field: keyof TourDailyDriverDTO, value: any) => {
    // Left empty since we now use multi-allocation modals to manage daily drivers
  };
  const [selectedTransportBlock, setSelectedTransportBlock] = useState<any>(null);
  const [showTransportReqModal, setShowTransportReqModal] = useState(false);
  const [isGlobalTransportReqEdit, setIsGlobalTransportReqEdit] = useState(false);
  const [globalTransportReq, setGlobalTransportReq] = useState<any>(null);
  const [modalTriggerRect, setModalTriggerRect] = useState<{ top: number; left: number; width: number; height: number } | null>(null);
  // Vehicle picker state inside the transport req modal
  const [reqPickedVehicles, setReqPickedVehicles] = useState<Array<{ vehicleId: string; vehicleName: string; providerName: string; quantity: number; notes: string }>>([]);
  const [reqShowVehiclePicker, setReqShowVehiclePicker] = useState(false);
  const [reqVehicleSearchMake, setReqVehicleSearchMake] = useState('');
  const [reqVehicleSearchMinYear, setReqVehicleSearchMinYear] = useState<number | ''>('');
  const [reqVehiclesLoading, setReqVehiclesLoading] = useState(false);

  const handleUpdateTransportReqField = (blockId: string | null, field: string, value: any) => {
    if (blockId === null) {
      setGlobalTransportReq((prev: any) => {
        const oldReq = prev || {};
        return {
          ...oldReq,
          [field]: value
        };
      });
    } else {
      setSelectedTransportBlock((prev: any) => {
        if (!prev) return null;
        const oldReq = prev.transport_requirement || {};
        return {
          ...prev,
          transport_requirement: {
            ...oldReq,
            [field]: value
          }
        };
      });

      // Update itinerary
      setItinerary(prev => prev.map(b => {
        const isMatch = b.id === blockId || (selectedTransportBlock?.daily_activities?.some((da: any) => da.id === b.id));
        if (isMatch) {
          const oldReq = b.transport_requirement || {};
          return {
            ...b,
            transport_requirement: {
              ...oldReq,
              [field]: value
            }
          };
        }
        return b;
      }));

      // Update poBlocks
      setPoBlocks(prev => prev.map(pb => {
        const matchesPOBlock = pb.id === blockId;
        const matchesActivity = pb.daily_activities?.some((da: any) => da.id === blockId);
        if (matchesPOBlock || matchesActivity) {
          const oldReq = pb.transport_requirement || {};
          return {
            ...pb,
            transport_requirement: {
              ...oldReq,
              [field]: value
            },
            daily_activities: (pb.daily_activities || []).map((da: any) => {
              if (matchesPOBlock || da.id === blockId) {
                const oldDaReq = da.transport_requirement || {};
                return {
                  ...da,
                  transport_requirement: {
                    ...oldDaReq,
                    [field]: value
                  }
                };
              }
              return da;
            })
          };
        }
        return pb;
      }));
    }
  };
  const [manualSingle, setManualSingle] = useState<number>(0);
  const [manualDouble, setManualDouble] = useState<number>(1);
  const [manualTriple, setManualTriple] = useState<number>(0);
  const [manualFamily, setManualFamily] = useState<number>(0);

  // Guide-Selection states
  const [guideActivities, setGuideActivities] = useState<any[]>([]);
  const [guideRatesState, setGuideRatesState] = useState<Record<string, Record<number, { rateType: string; contractedPrice: number; chargedPrice: number; note: string }>>>({});
  const [isLoadingGuideRates, setIsLoadingGuideRates] = useState(false);


  const [isSavingGuideRates, setIsSavingGuideRates] = useState<string | null>(null);

  const saveGuideRates = async (guideId: string) => {
    setIsSavingGuideRates(guideId);
    try {
      const guideRates = guideRatesState[guideId];
      if (!guideRates) return;

      const arrivalDate = touristData?.preferences?.arrival_date || '';
      const numDays = touristData?.preferences?.duration_days || 5;

      const activitiesToSave = [];

      for (let idx = 0; idx < numDays; idx++) {
        const dayNum = idx + 1;
        const rateData = guideRates[dayNum];
        if (!rateData) continue;

        let dateStr = '';
        if (arrivalDate) {
          try {
            const d = new Date(arrivalDate);
            d.setDate(d.getDate() + idx);
            dateStr = d.toISOString().split('T')[0];
          } catch (e) { }
        }

        activitiesToSave.push({
          day_number: dayNum,
          service_date: dateStr || null,
          quantity: 1,
          contracted_price: rateData.contractedPrice,
          contracted_total_price: rateData.contractedPrice,
          charged_unit_price: rateData.chargedPrice,
          charged_total_price: rateData.chargedPrice,
          description: rateData.note || `Rate Type: ${rateData.rateType}`
        });
      }

      const res = await saveGuideDailyActivitiesAction(tourId, guideId, activitiesToSave);
      if (res.success) {
        const reloadRes = await getGuideDailyActivitiesAction(tourId);
        if (reloadRes.success && reloadRes.activities) {
          setGuideActivities(reloadRes.activities);
        }
        alert("Guide rates saved successfully!");
      } else {
        alert(res.error || "Failed to save guide rates.");
      }
    } catch (err) {
      console.error("Error saving guide rates:", err);
      alert("Error saving guide rates.");
    } finally {
      setIsSavingGuideRates(null);
    }
  };


  // Driver-Selection states
  const [driverActivities, setDriverActivities] = useState<any[]>([]);
  const [driverRatesState, setDriverRatesState] = useState<Record<string, Record<number, { rateType: string; contractedPrice: number; chargedPrice: number; note: string }>>>({});
  const [isLoadingDriverRates, setIsLoadingDriverRates] = useState(false);
  const [isSavingDriverRates, setIsSavingDriverRates] = useState<string | null>(null);

  const saveDriverRates = async (driverId: string) => {
    setIsSavingDriverRates(driverId);
    try {
      const driverRates = driverRatesState[driverId];
      if (!driverRates) return;

      const arrivalDate = touristData?.preferences?.arrival_date || '';
      const numDays = touristData?.preferences?.duration_days || 5;

      const activitiesToSave = [];
      const assignmentsToSave: TourDailyDriverDTO[] = [];

      for (let idx = 0; idx < numDays; idx++) {
        const dayNum = idx + 1;
        const rateData = driverRates[dayNum];
        if (!rateData) continue;

        let dateStr = '';
        if (arrivalDate) {
          try {
            const d = new Date(arrivalDate);
            d.setDate(d.getDate() + idx);
            dateStr = d.toISOString().split('T')[0];
          } catch (e) { }
        }

        activitiesToSave.push({
          day_number: dayNum,
          service_date: dateStr || null,
          quantity: 1,
          contracted_price: rateData.contractedPrice,
          contracted_total_price: rateData.contractedPrice,
          charged_unit_price: rateData.chargedPrice,
          charged_total_price: rateData.chargedPrice,
          description: rateData.note || `Rate Type: ${rateData.rateType}`
        });

        assignmentsToSave.push({
          tour_id: tourId,
          day_number: dayNum,
          driver_id: driverId,
          contracted_per_day_rate: rateData.contractedPrice,
          charged_per_day_rate: rateData.chargedPrice,
          notes: rateData.note || rateData.rateType || ''
        } as TourDailyDriverDTO);
      }

      // Preserve existing assignments for OTHER drivers from dailyDriverAssignments
      const otherDriverPayloads: TourDailyDriverDTO[] = [];
      Object.entries(dailyDriverAssignments).forEach(([dNumStr, assignList]) => {
        const dNum = Number(dNumStr);
        (assignList || []).forEach((dAss: any) => {
          if (dAss.driver_id !== driverId) {
            otherDriverPayloads.push({
              tour_id: tourId,
              day_number: dNum,
              driver_id: dAss.driver_id,
              contracted_per_day_rate: Number(dAss.contracted_per_day_rate ?? dAss.per_day_rate ?? 0),
              charged_per_day_rate: Number(dAss.charged_per_day_rate ?? dAss.per_day_rate ?? 0),
              notes: dAss.notes || ''
            } as TourDailyDriverDTO);
          }
        });
      });

      const fullAssignmentsToSave = [...otherDriverPayloads, ...assignmentsToSave];
      const res = await saveTourDailyDriversAction(tourId, fullAssignmentsToSave);

      if (res.success) {
        const reloadDriversRes = await getTourDailyDriversAction(tourId);
        if (reloadDriversRes.success && reloadDriversRes.drivers) {
          const groupedDrivers: Record<number, any[]> = {};
          reloadDriversRes.drivers.forEach((dAss: any) => {
            const dayN = Number(dAss.day_number || 1);
            if (!groupedDrivers[dayN]) groupedDrivers[dayN] = [];
            groupedDrivers[dayN].push(dAss);
          });
          setDailyDriverAssignments(groupedDrivers);
        }
        const blocksRes = await getPOBlocksAction(tourId);
        if (blocksRes.success && blocksRes.blocks) {
          setPoBlocks(blocksRes.blocks);
        }
        alert("Driver rates saved successfully!");
      } else {
        alert(res.error || "Failed to save driver rates.");
      }
    } catch (err) {
      console.error("Error saving driver rates:", err);
      alert("Error saving driver rates.");
    } finally {
      setIsSavingDriverRates(null);
    }
  };

  // Master Data State for Binders
  const [masterData, setMasterData] = useState<any>({
    hotels: [],
    vendors: [],
    drivers: [],
    guides: [],
    restaurants: [],
    transportProviders: [],
    transportVehicles: [],
    activities: []
  });

  const filteredMasterData = useMemo(() => {
    if (!activeAssignment) return [];
    const terms = searchTerm.toLowerCase().split(/\s+/).filter(Boolean);

    const checkMatch = (fields: (string | undefined | null)[]) => {
      if (terms.length === 0) return true;
      const combined = fields.filter(f => f).map(f => f!.toLowerCase()).join(' ');
      return terms.every(t => combined.includes(t));
    };

    switch (activeAssignment.type) {
      case ItineraryBlockTypes.SLEEP:
        return masterData.hotels.filter((h: any) => checkMatch([h.name, h.closest_city, h.location_address]));
      case ItineraryBlockTypes.ACTIVITY:
        return masterData.vendors.filter((v: any) => {
          const activityStrings = v.vendor_activities?.flatMap((va: any) => {
            const actData = (va as any).activities || (va as any).activity;
            return [
              va.activity_name,
              actData?.location_name,
              actData?.district
            ];
          }) || [];
          return checkMatch([v.name, v.address, ...activityStrings]);
        });
      case ItineraryBlockTypes.MEAL:
        return masterData.restaurants.filter((r: any) => checkMatch([r.name, r.address, r.city, r.district]));
      case ItineraryBlockTypes.TRAVEL:
        return {
          providers: masterData.transportProviders.filter((p: any) => checkMatch([p.name, p.address])),
          drivers: masterData.drivers.filter((d: any) => checkMatch([d.first_name, d.last_name]))
        };
      case ItineraryBlockTypes.GUIDE:
        return masterData.guides.filter((g: any) => checkMatch([g.first_name, g.last_name]));
      default:
        return [];
    }
  }, [activeAssignment, searchTerm, masterData]);

  // Lock background scroll when assignment drawer is active
  useEffect(() => {
    const mainScrollContainer = document.getElementById('main-scroll-container');
    if (activeAssignment) {
      document.body.style.overflow = 'hidden';
      if (mainScrollContainer) {
        mainScrollContainer.style.overflow = 'hidden';
      }
    } else {
      document.body.style.overflow = '';
      if (mainScrollContainer) {
        mainScrollContainer.style.overflow = '';
      }
    }
    return () => {
      document.body.style.overflow = '';
      if (mainScrollContainer) {
        mainScrollContainer.style.overflow = '';
      }
    };
  }, [activeAssignment]);

  // Load master data on mount
  useEffect(() => {
    async function loadData() {
      setLoadingMaster(true);
      try {
        const assignedHotelIds = itinerary
          .filter(b => b.type === ItineraryBlockTypes.SLEEP && b.hotelId)
          .map(b => b.hotelId as string);

        const [h, v, d, g, r, tp, act, markupRes, vehiclesRes] = await Promise.all([
          getAssignedHotelsAction(assignedHotelIds),
          getVendorsAction(),
          getDriversAction(),
          getTourGuidesAction(),
          getRestaurantsAction(),
          getTransportProvidersAction(),
          getActivitiesAction(),
          getAppMarkupsAction(),
          getTransportVehiclesAction()
        ]);
        const providersList = tp.success ? tp.providers : [];
        const vehiclesList = vehiclesRes.success ? vehiclesRes.vehicles : [];
        setMasterData({
          hotels: h.success ? h.hotels : [],
          vendors: v.success ? v.vendors : [],
          drivers: d.success ? d.drivers : [],
          guides: g.success ? g.guides : [],
          restaurants: r.success ? r.restaurants : [],
          transportProviders: providersList,
          transportVehicles: vehiclesList,
          activities: act.success ? (act.data || (act as any).activities || []) : []
        });
        if (markupRes && markupRes.success && markupRes.markups) {
          setMarkups(markupRes.markups);
          setRoomMarkup(markupRes.markups[Settings.Room_Markup] ?? 10);
        }
      } catch (err) {
        console.error("Failed to load master data for assignment:", err);
      } finally {
        setLoadingMaster(false);
      }
    }
    if (tourId) {
      loadData();
    }
  }, [tourId]);

  const handleSearchHotels = async () => {
    setIsSearchingHotels(true);
    try {
      const res = await searchHotelsAction(hotelSearchCity, hotelSearchName);
      if (res.success && res.hotels) {
        setHotelSearchResults(res.hotels);
        // Merge into masterData.hotels
        setMasterData((prev: any) => {
          const existingIds = new Set(prev.hotels.map((h: any) => h.id));
          const newHotels = res.hotels.filter((h: any) => !existingIds.has(h.id));
          return { ...prev, hotels: [...prev.hotels, ...newHotels] };
        });
      } else {
        setHotelSearchResults([]);
      }
    } catch (err) {
      console.error(err);
      setHotelSearchResults([]);
    } finally {
      setIsSearchingHotels(false);
    }
  };

  const handleSearchRestaurants = async () => {
    setIsSearchingRestaurants(true);
    try {
      const combinedSearch = `${restaurantSearchCity} ${restaurantSearchName}`.trim();
      const res = await searchRestaurantsAction(combinedSearch);
      if (res.success && res.restaurants) {
        setRestaurantSearchResults(res.restaurants);
        // Merge into masterData.restaurants
        setMasterData((prev: any) => {
          const existingIds = new Set(prev.restaurants.map((r: any) => r.id));
          const newRestaurants = res.restaurants.filter((r: any) => !existingIds.has(r.id));
          return { ...prev, restaurants: [...prev.restaurants, ...newRestaurants] };
        });
      } else {
        setRestaurantSearchResults([]);
      }
    } catch (err) {
      console.error(err);
      setRestaurantSearchResults([]);
    } finally {
      setIsSearchingRestaurants(false);
    }
  };

  const updateBlock = (id: string, fields: Partial<InternalItineraryBlock>) => {
    setItinerary(prev => prev.map(b => b.id === id ? { ...b, ...fields } : b));
  };

  const bindProvider = (blockId: string, field: keyof InternalItineraryBlock, value: any) => {
    const block = itinerary.find(b => b.id === blockId);
    if (!block) return;

    // Sync logic for hotels
    if (field === 'hotelId' && block.type === ItineraryBlockTypes.SLEEP) {
      const hotel = masterData.hotels.find((h: any) => h.id === value);
      if (hotel) {
        // Auto-populate cover image if available
        const autoImageUrl = (hotel.images && hotel.images.length > 0) ? hotel.images[0] : (hotel.photo_url || block.imageUrl || '');
        const computedRate = computeHotelRateForBlock(hotel, block.mealPlan || 'BB', block.roomName);
        const baseRate = computedRate > 0 ? computedRate : (block.baseRoomRate || 0);

        const oldHotelId = block.hotelId;

        if (track === 'final' && oldHotelId) {
          const newLocationName = hotel.closest_city || hotel.location_address || '';
          const currentDay = Number(block.dayNumber);

          // 1. Update ONLY this block in itinerary
          setItinerary(prev => prev.map(b => b.id === blockId ? {
            ...b,
            hotelId: value,
            hotelName: hotel.name,
            imageUrl: autoImageUrl,
            locationName: newLocationName,
            roomName: '',
            mealPlan: 'BB',
            baseRoomRate: baseRate > 0 ? baseRate : b.baseRoomRate,
            agreedPrice: baseRate > 0 ? baseRate : b.agreedPrice
          } : b));

          // 2. Update ONLY this activity in dbActivities
          setDbActivities(prev => prev.map(act => {
            return act.id === blockId ? {
              ...act,
              hotel_id: value,
              hotel_room_id: null,
              location_name: newLocationName,
              quantity: 1,
              charged_unit_price: null,
              charged_total_price: null,
              contracted_price: null,
              contracted_total_price: null,
              single_room_id: null,
              single_room_count: 0,
              double_room_id: null,
              double_room_count: 0,
              twin_room_id: null,
              twin_room_count: 0,
              triple_room_id: null,
              triple_room_count: 0,
              family_room_id: null,
              family_room_count: 0
            } : act;
          }));

          // 3. Update ONLY this accommodation in tripData
          if (tripData) {
            let newAccs = [...(tripData.accommodations || [])];
            newAccs = newAccs.map(a => Number(a.nightIndex) === currentDay ? {
              ...a,
              hotelId: hotel.id,
              hotelName: hotel.name,
              stayClass: hotel.hotel_class || 'Standard',
              address: hotel.location_address || '',
              roomId: undefined,
              roomName: '',
              roomStandard: '',
              pricePerNight: baseRate,
              selectedRooms: []
            } : a);
            setTripData({
              ...tripData,
              accommodations: newAccs
            });
          }
        } else {
          setItinerary(prev => prev.map(b => b.id === blockId ? {
            ...b,
            hotelId: value,
            hotelName: hotel.name,
            imageUrl: autoImageUrl,
            baseRoomRate: baseRate > 0 ? baseRate : b.baseRoomRate,
            agreedPrice: baseRate > 0 ? baseRate : b.agreedPrice,
            // reset room specific selections if switching to a different hotel (do NOT reset agreedPrice)
            ...(b.hotelId !== value ? { roomName: '', mealPlan: 'BB' } : {})
          } : b));

          if (tripData) {
            let newAccs = [...(tripData.accommodations || [])];
            const existingAccIndex = newAccs.findIndex(a => Number(a.nightIndex) === Number(block.dayNumber));
            if (existingAccIndex >= 0) {
              newAccs[existingAccIndex] = {
                ...newAccs[existingAccIndex],
                hotelId: hotel.id,
                hotelName: hotel.name,
                stayClass: hotel.hotel_class || newAccs[existingAccIndex].stayClass,
                address: hotel.location_address || newAccs[existingAccIndex].address,
                ...(newAccs[existingAccIndex].hotelId !== hotel.id ? { roomId: undefined, roomName: '', roomStandard: '', mealPlan: undefined, pricePerNight: 0, selectedRooms: [] } : {})
              };
            } else {
              newAccs.push({
                id: crypto.randomUUID(),
                nightIndex: block.dayNumber,
                hotelId: hotel.id,
                hotelName: hotel.name,
                stayClass: hotel.hotel_class || 'Standard',
                address: hotel.location_address || '',
                mapLink: '',
                contactPerson: hotel.reservation_agent_name || '',
                contactNumber: hotel.reservation_agent_contact || '',
                email: '',
                rateCardUrl: '',
                roomStandard: 'Standard Room',
                numberOfRooms: 1,
                pricePerNight: 0,
                mealPlan: 'BB',
                status: 'Tentative',
                confirmationReference: '',
                paymentStatus: 'Pending',
                cancellationDeadline: '',
                beddingConfiguration: '',
                specialRequests: '',
                selectedRooms: []
              });
            }
            setTripData({
              ...tripData,
              accommodations: newAccs
            });
          }
        }
      }
    }

    // Sync logic for restaurants
    else if (field === 'restaurantId' && block.type === ItineraryBlockTypes.MEAL) {
      const restaurant = masterData.restaurants.find((r: any) => r.id === value);
      if (restaurant) {
        const contractedPrice = restaurant.lunch_rate_per_head || 25;
        const travelStyle = tripData?.profile?.travelStyle || 'Luxury';
        const styleKey = TravelStyleSettingKeys[travelStyle as Exclude<TravelStyle, 'Mixed'>] || 'luxury';
        const mealLabel = block.mealType || 'Lunch';
        const appSettingKey = `${styleKey}_${mealLabel.toLowerCase()}_cost`;
        const baseCost = appSettings && appSettings[appSettingKey] !== undefined
          ? Number(appSettings[appSettingKey])
          : (mealLabel === 'Breakfast' ? 15 : mealLabel === 'Lunch' ? 25 : 35);
        const markupPercent = appSettings && appSettings['restaurant_markup'] !== undefined
          ? Number(appSettings['restaurant_markup'])
          : 10;
        const unitCharged = baseCost * (1 + markupPercent / 100);

        setItinerary(prev => prev.map(b => b.id === blockId ? {
          ...b,
          restaurantId: value,
          contractedPrice: b.contractedPrice ?? contractedPrice,
          agreedPrice: unitCharged
        } : b));
      }
    }

    else if (field === 'activityId' && block.type === ItineraryBlockTypes.ACTIVITY) {
      const activity = masterData.activities.find((a: any) => a.id === value);
      if (activity) {
        const autoImageUrl = (activity.images && activity.images.length > 0) ? activity.images[0] : (block.imageUrl || '');
        setItinerary(prev => prev.map(b => b.id === blockId ? {
          ...b,
          activityId: value,
          imageUrl: autoImageUrl,
          ...(b.activityId !== value ? { vendorId: undefined, vendorActivityId: undefined, contractedPrice: undefined, agreedPrice: undefined } : {})
        } : b));
      }
    }

    // Sync logic for activities (Vendors)
    else if (field === 'vendorId' && block.type === ItineraryBlockTypes.ACTIVITY) {
      const vendor = masterData.vendors.find((v: any) => v.id === value);
      if (vendor) {
        const blockActivityId = block.activityId || (() => {
          if (!block.name) return undefined;
          const cleanWords = (str: string) => {
            return str.toLowerCase()
              .replace(/[^\w\s]/g, '')
              .split(/\s+/)
              .filter(w => w.length > 2 && !['visit', 'explore', 'climb', 'tour', 'the', 'and', 'for', 'with', 'to', 'in', 'at'].includes(w));
          };
          const blockWords = cleanWords(block.name);
          if (blockWords.length === 0) return undefined;

          let bestMatch: any = null;
          let maxOverlap = 0;
          masterData.activities.forEach((a: any) => {
            const actWords = cleanWords(a.activity_name);
            const overlap = blockWords.filter(w => actWords.includes(w)).length;
            if (overlap > maxOverlap) {
              maxOverlap = overlap;
              bestMatch = a;
            }
          });
          return maxOverlap > 0 ? bestMatch?.id : undefined;
        })();

        const va = vendor.vendor_activities?.find((a: any) => Number(a.activity_id) === Number(blockActivityId));

        // Auto-populate cover image if available
        const activityDetail = masterData.activities.find((a: any) => Number(a.id) === Number(blockActivityId));
        const autoImageUrl = (activityDetail?.images && activityDetail.images.length > 0)
          ? activityDetail.images[0]
          : (block.imageUrl || '');

        if (va) {
          const markupPercent = markups[Settings.Vendor_Activity_Markup] ?? 10;
          const contractedRate = va.vendor_price || 0;
          const agreedPrice = contractedRate * (1 + markupPercent / 100);

          setItinerary(prev => prev.map(b => b.id === blockId ? {
            ...b,
            vendorId: value,
            activityId: blockActivityId,
            vendorActivityId: va.id,
            contractedPrice: b.contractedPrice ?? contractedRate,
            agreedPrice: b.agreedPrice ?? agreedPrice,
            imageUrl: autoImageUrl
          } : b));
        } else {
          setItinerary(prev => prev.map(b => b.id === blockId ? {
            ...b,
            vendorId: value,
            activityId: blockActivityId,
            vendorActivityId: undefined,
            contractedPrice: b.contractedPrice,
            agreedPrice: b.agreedPrice,
            imageUrl: autoImageUrl
          } : b));
        }
      }
    }

    // Sync logic for transport defaults
    else if (field === 'transportId' && block.type === ItineraryBlockTypes.TRAVEL) {
      const provider = masterData.transportProviders.find((p: any) => p.id === value);
      if (provider) {
        setItinerary(prev => prev.map(b => b.id === blockId ? {
          ...b,
          transportId: value,
          transportRateType: 'day',
          transportQuantity: 1
        } : b));
      }
    }
  };

  const getSleepHotelForDay = (dayNum: number) => {
    const sleepBlock = itinerary.find(b => b.dayNumber === dayNum && b.type === ItineraryBlockTypes.SLEEP);
    if (sleepBlock && sleepBlock.hotelId) {
      const h = masterData.hotels?.find((x: any) => x.id === sleepBlock.hotelId);
      return {
        hotelId: sleepBlock.hotelId,
        hotelName: sleepBlock.hotelName || h?.name || 'Hotel on Day ' + dayNum
      };
    }
    return null;
  };

  const getBindingDisplay = (block: InternalItineraryBlock) => {
    if (block.type === ItineraryBlockTypes.SLEEP && block.hotelId) {
      const h = masterData.hotels.find((x: any) => x.id === block.hotelId);
      let label = h?.name || block.hotelName || 'Linked Hotel';
      if (block.roomName) {
        label += ` - ${block.roomName}`;
      }
      if (block.mealPlan) {
        label += ` (${block.mealPlan})`;
      }
      return {
        name: label,
        icon: <BedDouble className="w-3.5 h-3.5 text-indigo-500" />,
        contact: h ? {
          name: h.sales_agent_name || h.reservation_agent_name || h.gm_name || 'Reservations / Sales',
          phone: h.sales_agent_contact || h.reservation_agent_contact || h.gm_contact || ''
        } : undefined
      };
    }
    if (block.type === ItineraryBlockTypes.ACTIVITY) {
      if (block.hotelId) {
        const h = masterData.hotels.find((x: any) => x.id === block.hotelId);
        let label = `Hotel Provider: ${h?.name || block.hotelName || 'Linked Hotel'}`;
        return {
          name: label,
          icon: <BedDouble className="w-3.5 h-3.5 text-indigo-500" />,
          contact: h ? {
            name: h.sales_agent_name || h.reservation_agent_name || h.gm_name || 'Reservations / Sales',
            phone: h.sales_agent_contact || h.reservation_agent_contact || h.gm_contact || ''
          } : undefined
        };
      }
      const v = block.vendorId ? masterData.vendors.find((x: any) => x.id === block.vendorId) : null;
      const resolvedActId = block.activityId || (() => {
        if (!block.name) return undefined;
        const cleanWords = (str: string) => {
          return str.toLowerCase()
            .replace(/[^\w\s]/g, '')
            .split(/\s+/)
            .filter(w => w.length > 2 && !['visit', 'explore', 'climb', 'tour', 'the', 'and', 'for', 'with', 'to', 'in', 'at', 'relax', 'unwind', 'leisure', 'hotel', 'stay', 'free', 'day', 'rest', 'evening', 'morning', 'afternoon', 'safari', 'hike', 'walk', 'trek', 'ride', 'drive', 'boat', 'boating', 'cruise', 'beach', 'lake', 'river', 'park', 'national', 'temple', 'fort', 'gardens', 'garden', 'waterfall', 'waterfalls', 'sightseeing', 'city', 'shopping', 'dinner', 'lunch', 'breakfast', 'meal', 'meals', 'transfer', 'transfers', 'arrival', 'departure', 'flight', 'flights', 'activity', 'activities', 'attraction', 'attractions'].includes(w));
        };
        const blockWords = cleanWords(block.name);
        if (blockWords.length === 0) return undefined;

        let bestMatch: any = null;
        let maxOverlap = 0;
        masterData.activities.forEach((a: any) => {
          const actWords = cleanWords(a.activity_name);
          const overlap = blockWords.filter(w => actWords.includes(w)).length;
          if (overlap > maxOverlap) {
            maxOverlap = overlap;
            bestMatch = a;
          }
        });
        return maxOverlap > 0 ? bestMatch?.id : undefined;
      })();
      const va = v?.vendor_activities?.find((x: any) => x.id === block.vendorActivityId) ||
        v?.vendor_activities?.find((x: any) => Number(x.activity_id) === Number(resolvedActId));

      if (v) {
        const activityLabel = va?.activity_name || block.name || 'Activity';
        let label = `${v.name} - ${activityLabel}`;
        return {
          name: label,
          icon: <Compass className="w-3.5 h-3.5 text-orange-500" />,
          contact: { name: 'Vendor', phone: v.phone || '' }
        };
      }

      const activityDetail = masterData.activities.find((x: any) => Number(x.id) === Number(resolvedActId));
      let fallbackLabel = activityDetail?.activity_name || block.name || 'Linked Activity';

      return { name: fallbackLabel, icon: <Compass className="w-3.5 h-3.5 text-orange-500" /> };
    }
    if (block.type === ItineraryBlockTypes.TRAVEL && (block.driverId || block.transportId || block.vehicleId)) {
      const d = masterData.drivers.find((x: any) => x.id === block.driverId);
      const p = masterData.transportProviders.find((x: any) => x.id === block.transportId);
      const v = p?.transport_vehicles?.find((x: any) => x.id === block.vehicleId);

      let label = p?.name || 'Transport Provider';
      let contact = undefined;
      if (v) {
        label = `${p?.name || ''} - ${[v.make, v.model].filter(Boolean).join(' ') || v.make_and_model || v.vehicle_type}`;
        if (block.transportQuantity) {
          label += ` [${block.transportQuantity} ${block.transportRateType === 'km' ? 'KM' : 'Day(s)'}]`;
        }
        if (v.with_driver) label += ' [Incl. Driver]';
        else if (d) label += ` [Driver: ${d.first_name}]`;

        if (d) contact = { name: `${d.first_name} (Driver)`, phone: d.phone || '' };
        else if (p) contact = { name: p.name, phone: p.phone || '' };

      } else if (d) {
        label = `Driver: ${d.first_name} ${d.last_name}`;
        contact = { name: `${d.first_name} (Driver)`, phone: d.phone || '' };
      } else if (p) {
        contact = { name: p.name, phone: p.phone || '' };
      }

      return { name: label, icon: <Car className="w-3.5 h-3.5 text-blue-500" />, contact };
    }
    if (block.type === ItineraryBlockTypes.GUIDE && block.guideId) {
      const g = masterData.guides.find((x: any) => x.id === block.guideId);
      return {
        name: g ? `${g.first_name} ${g.last_name}` : 'Linked Guide',
        icon: <UserCheck className="w-3.5 h-3.5 text-amber-500" />,
        contact: g ? { name: g.first_name, phone: g.phone || '' } : undefined
      };
    }
    if (block.type === ItineraryBlockTypes.MEAL && block.restaurantId) {
      const r = masterData.restaurants.find((x: any) => x.id === block.restaurantId);
      let label = r?.name || 'Linked Restaurant';
      if (block.mealType) label += ` - ${block.mealType}`;
      return {
        name: label,
        icon: <Utensils className="w-3.5 h-3.5 text-green-500" />,
        contact: r ? { name: r.contact_name || r.name, phone: r.contact_number || '' } : undefined
      };
    }
    return null;
  };

  const handleCopyRatePrompt = (block: InternalItineraryBlock) => {
    if (block.type !== ItineraryBlockTypes.SLEEP || !block.hotelId) return;
    const hotel = masterData.hotels.find((h: any) => h.id === block.hotelId);
    if (!hotel) return;

    let checkInStr = "<check_in_date>";
    let checkOutStr = "<check_out_date>";

    if (touristData?.preferences?.arrival_date) {
      const checkInDate = new Date(touristData.preferences.arrival_date);
      checkInDate.setDate(checkInDate.getDate() + (block.dayNumber - 1));

      const checkOutDate = new Date(checkInDate);
      checkOutDate.setDate(checkOutDate.getDate() + 1);

      checkInStr = checkInDate.toISOString().split('T')[0];
      checkOutStr = checkOutDate.toISOString().split('T')[0];
    }

    const hotelName = hotel.name || "<hotel_name>";
    const hotelLocation = hotel.closest_city || "<hotel_location>";
    const mealPlan = block.mealPlan || "BB";
    const adults = touristData?.preferences?.adults || 2;
    const children = touristData?.preferences?.children || 0;

    const prompt = `Could you please provide the rate for a stay at ${hotelName} in ${hotelLocation} for ${adults} adults and ${children} children, from ${checkInStr} to ${checkOutStr}, on a ${mealPlan} basis?`;

    navigator.clipboard.writeText(prompt);
    window.alert("Rate prompt copied to clipboard:\n\n" + prompt);
  };

  // Synchronize tripData accommodations changes back into dbActivities list in memory
  useEffect(() => {
    setDbActivities(prev => {
      let changed = false;
      const updated = prev.map(act => {
        const isCustom = !!act.isCustomPO;
        if ((act.activity_type === 'sleep' || act.hotel_id) && !isCustom) {
          const dayNum = act.tour_itineraries?.day_number || act.day_number || act.dayNumber || 0;
          const acc = tripData?.accommodations?.find(a => Number(a.nightIndex) === Number(dayNum));
          if (acc) {
            let totalRooms = 0;
            let totalAgreedPrice = 0;
            let totalContractedPrice = 0;
            let mealPlan = acc.mealPlan || 'BB';

            let single_room_id = null;
            let single_room_count = 0;
            let double_room_id = null;
            let double_room_count = 0;
            let twin_room_id = null;
            let twin_room_count = 0;
            let triple_room_id = null;
            let triple_room_count = 0;
            let family_room_id = null;
            let family_room_count = 0;

            if (acc.selectedRooms && acc.selectedRooms.length > 0) {
              acc.selectedRooms.forEach(room => {
                totalRooms += room.quantity;
                totalAgreedPrice += (room.pricePerNight || 0) * room.quantity;
                totalContractedPrice += (room.contractedPrice || room.pricePerNight || 0) * room.quantity;
                if (room.mealPlan) mealPlan = room.mealPlan;

                const reqType = room.reqId?.split('-')[0];
                if (reqType === 'Single') {
                  single_room_id = room.roomId || null;
                  single_room_count = room.quantity;
                } else if (reqType === 'Double') {
                  double_room_id = room.roomId || null;
                  double_room_count = room.quantity;
                } else if (reqType === 'Twin') {
                  twin_room_id = room.roomId || null;
                  twin_room_count = room.quantity;
                } else if (reqType === 'Triple') {
                  triple_room_id = room.roomId || null;
                  triple_room_count = room.quantity;
                } else if (reqType === 'Family') {
                  family_room_id = room.roomId || null;
                  family_room_count = room.quantity;
                }
              });
            } else {
              totalRooms = acc.numberOfRooms || 1;
              totalAgreedPrice = (acc.pricePerNight || 0) * totalRooms;
              totalContractedPrice = ((acc as any).contractedPrice || acc.pricePerNight || 0) * totalRooms;

              // Fallback to double room mapping if single roomId is present on accommodation
              const assumedRoomId = acc.roomId || null;
              double_room_id = assumedRoomId;
              double_room_count = totalRooms;
            }

            const unitPrice = totalRooms > 0 ? totalAgreedPrice / totalRooms : 0;
            const newRoomId = acc.roomId || (acc.selectedRooms?.[0]?.roomId) || null;

            let finalContractedUnitPrice = totalRooms > 0 ? totalContractedPrice / totalRooms : 0;
            let finalContractedPrice = totalContractedPrice;
            if (acc.customContractedUnitPrice !== undefined || acc.customContractedTotalPrice !== undefined) {
              finalContractedUnitPrice = acc.customContractedUnitPrice ?? (acc.customContractedTotalPrice ? acc.customContractedTotalPrice / (totalRooms || 1) : 0);
              finalContractedPrice = acc.customContractedTotalPrice ?? (finalContractedUnitPrice * totalRooms);
            }

            const expectedDescription = acc.customRateNote || null;

            const hotel = masterData.hotels?.find((h: any) => h.id === acc.hotelId);
            const newLocationName = hotel ? (hotel.closest_city || hotel.location_address || '') : '';

            if (
              act.hotel_id !== acc.hotelId ||
              act.hotel_room_id !== newRoomId ||
              act.quantity !== totalRooms ||
              act.meal_plan !== mealPlan ||
              act.location_name !== newLocationName ||
              act.description !== expectedDescription ||
              act.single_room_id !== single_room_id ||
              act.single_room_count !== single_room_count ||
              act.double_room_id !== double_room_id ||
              act.double_room_count !== double_room_count ||
              act.twin_room_id !== twin_room_id ||
              act.twin_room_count !== twin_room_count ||
              act.triple_room_id !== triple_room_id ||
              act.triple_room_count !== triple_room_count ||
              act.family_room_id !== family_room_id ||
              act.family_room_count !== family_room_count
            ) {
              changed = true;
              return {
                ...act,
                hotel_id: acc.hotelId || null,
                hotel_room_id: newRoomId,
                quantity: totalRooms,
                meal_plan: mealPlan,
                location_name: newLocationName,
                description: expectedDescription,
                single_room_id,
                single_room_count,
                double_room_id,
                double_room_count,
                twin_room_id,
                twin_room_count,
                triple_room_id,
                triple_room_count,
                family_room_id,
                family_room_count
              };
            }
          } else {
            // No accommodation bound for this night! Clear room selection fields but preserve activity prices.
            if (
              act.hotel_id !== null ||
              act.hotel_room_id !== null ||
              act.single_room_id !== null ||
              act.single_room_count !== 0 ||
              act.double_room_id !== null ||
              act.double_room_count !== 0 ||
              act.twin_room_id !== null ||
              act.twin_room_count !== 0 ||
              act.triple_room_id !== null ||
              act.triple_room_count !== 0 ||
              act.family_room_id !== null ||
              act.family_room_count !== 0
            ) {
              changed = true;
              return {
                ...act,
                hotel_id: null,
                hotel_room_id: null,
                single_room_id: null,
                single_room_count: 0,
                double_room_id: null,
                double_room_count: 0,
                twin_room_id: null,
                twin_room_count: 0,
                triple_room_id: null,
                triple_room_count: 0,
                family_room_id: null,
                family_room_count: 0
              };
            }
          }
        }
        return act;
      });
      return changed ? updated : prev;
    });
  }, [tripData?.accommodations, masterData.hotels]);

  const handleCustomRateUnitChange = (unitValStr: string, qty: number) => {
    setCustomRateUnit(unitValStr);
    const unitVal = parseFloat(unitValStr);
    if (!isNaN(unitVal)) {
      setCustomRateTotal((unitVal * qty).toFixed(2));
    } else {
      setCustomRateTotal('');
    }
  };

  const handleCustomRateTotalChange = (totalValStr: string, qty: number) => {
    setCustomRateTotal(totalValStr);
    const totalVal = parseFloat(totalValStr);
    if (!isNaN(totalVal) && qty > 0) {
      setCustomRateUnit((totalVal / qty).toFixed(2));
    } else {
      setCustomRateUnit('');
    }
  };

  const handleApplyCustomRateOverride = () => {
    if (!editingCustomRateAct || !tripData) return;
    const dayNum = editingCustomRateAct.tour_itineraries?.day_number || editingCustomRateAct.day_number || editingCustomRateAct.dayNumber || 0;

    const parsedUnit = parseFloat(customRateUnit);
    const parsedTotal = parseFloat(customRateTotal);
    const unitPrice = isNaN(parsedUnit) ? undefined : parsedUnit;
    const totalPrice = isNaN(parsedTotal) ? undefined : parsedTotal;
    const note = customRateNote.trim() || undefined;

    setIsApplyingRateOverride(true);

    const actId = editingCustomRateAct.id;
    const parentBlock = poBlocks.find(block =>
      (block.daily_activities || []).some((act: any) => act.id === actId)
    );
    const applyToAll = customRateApplyToAllInBlock && !!parentBlock;

    const targetActIds = applyToAll
      ? (parentBlock?.daily_activities || []).map((act: any) => act.id)
      : [actId];

    const targetDayNums = applyToAll
      ? (parentBlock?.daily_activities || []).map((act: any) =>
        Number(act.tour_itineraries?.day_number || act.day_number || act.dayNumber || 0)
      ).filter(Boolean)
      : [Number(dayNum)];

    setTripData({
      ...tripData,
      accommodations: tripData.accommodations.map(a => {
        const isMatch = targetDayNums.some(d => Number(d) === Number(a.nightIndex)) && a.hotelId === editingCustomRateAct.hotel_id;
        if (isMatch) {
          return {
            ...a,
            customContractedUnitPrice: Number(a.nightIndex) === Number(dayNum) ? unitPrice : a.customContractedUnitPrice,
            customContractedTotalPrice: Number(a.nightIndex) === Number(dayNum) ? totalPrice : a.customContractedTotalPrice,
            customRateNote: note,
          };
        }
        return a;
      })
    });

    // Update itinerary block state to persist via debounced saveTourAction
    setItinerary(prev =>
      prev.map(b => {
        const isMatch = targetActIds.includes(b.id);
        if (!isMatch) return b;
        return {
          ...b,
          driverMealIncluded: customRateDriverMeal,
          driverAccIncluded: customRateDriverAcc,
          parkingIncluded: customRateParking,
          guideRoomDiscount: customRateGuideRoomDiscount === 'None' ? undefined : (customRateGuideRoomDiscount as any)
        };
      })
    );

    // Update dbActivities state immediately
    setDbActivities(prev =>
      prev.map(act => {
        if (!targetActIds.includes(act.id)) return act;
        const isCurrent = act.id === actId;
        return {
          ...act,
          driver_meal_included: customRateDriverMeal,
          driver_acc_included: customRateDriverAcc,
          parking_included: customRateParking,
          guide_room_discount: customRateGuideRoomDiscount === 'None' ? null : customRateGuideRoomDiscount,
          contracted_price: isCurrent ? (unitPrice ?? act.contracted_price) : act.contracted_price,
          contracted_total_price: isCurrent ? (totalPrice ?? act.contracted_total_price) : act.contracted_total_price,
          description: note ?? act.description
        };
      })
    );

    // Also patch poBlocks state immediately so hotel-selection reflects the new
    // contracted rates and driver/parking options without requiring a full page reload.
    if (actId) {
      setPoBlocks(prev =>
        prev.map(block => ({
          ...block,
          daily_activities: (block.daily_activities || []).map((act: any) => {
            if (!targetActIds.includes(act.id)) return act;
            const isCurrent = act.id === actId;
            return {
              ...act,
              contracted_price: isCurrent ? (unitPrice ?? act.contracted_price) : act.contracted_price,
              contracted_total_price: isCurrent ? (totalPrice ?? act.contracted_total_price) : act.contracted_total_price,
              description: note ?? act.description,
              driver_meal_included: customRateDriverMeal,
              driver_acc_included: customRateDriverAcc,
              parking_included: customRateParking,
              guide_room_discount: customRateGuideRoomDiscount === 'None' ? null : customRateGuideRoomDiscount
            };
          }),
        }))
      );
    }

    setEditingCustomRateAct(null);

    // Persist to DB directly and immediately
    if (actId) {
      const updates = targetActIds.map(id => {
        const isCurrent = id === actId;
        return {
          id: id,
          contracted_price: isCurrent ? (unitPrice !== undefined ? unitPrice : null) : undefined,
          contracted_total_price: isCurrent ? (totalPrice !== undefined ? totalPrice : null) : undefined,
          driver_meal_included: customRateDriverMeal,
          driver_acc_included: customRateDriverAcc,
          parking_included: customRateParking,
          guide_room_discount: customRateGuideRoomDiscount === 'None' ? null : customRateGuideRoomDiscount
        };
      });

      finalizeActivityPricesAction(updates)
        .then(async (res) => {
          if (res.success && tourId) {
            const posRes = await getPurchaseOrdersAction(tourId);
            if (posRes.success && posRes.pos) setPurchaseOrders(posRes.pos);
          }
        })
        .catch(err => console.error('Rate override persist failed:', err))
        .finally(() => setIsApplyingRateOverride(false));
    } else {
      setIsApplyingRateOverride(false);
    }
  };

  /**
   * For non-hotel steps (restaurant, activity, transport):
   * persists the rate override directly to daily_activities via DB action
   * and patches poBlocks state optimistically.
   */
  const handleApplyDirectRateOverride = () => {
    if (!editingCustomRateAct) return;
    const parsedUnit = parseFloat(customRateUnit);
    const parsedTotal = parseFloat(customRateTotal);
    const unitPrice = isNaN(parsedUnit) ? undefined : parsedUnit;
    const totalPrice = isNaN(parsedTotal) ? undefined : parsedTotal;

    if (unitPrice === undefined && totalPrice === undefined) return;

    setIsApplyingRateOverride(true);

    // Support multi-leg day groups: distribute total evenly, remainder to first leg
    const allLegIds: string[] = editingCustomRateAct._allLegIds || [editingCustomRateAct.id];
    const numLegs = allLegIds.length;
    const perLegTotal = totalPrice !== undefined ? parseFloat((totalPrice / numLegs).toFixed(2)) : undefined;
    const firstLegTotal = totalPrice !== undefined
      ? parseFloat((totalPrice - (perLegTotal! * (numLegs - 1))).toFixed(2))
      : undefined;

    // Optimistic patch
    setPoBlocks(prev => prev.map(block => ({
      ...block,
      daily_activities: (block.daily_activities || []).map((act: any) => {
        const legIdx = allLegIds.indexOf(act.id);
        if (legIdx === -1) return act;
        return {
          ...act,
          contracted_price: unitPrice ?? act.contracted_price,
          contracted_total_price: (legIdx === 0 ? firstLegTotal : perLegTotal) ?? act.contracted_total_price,
          description: customRateNote.trim() || act.description,
        };
      }),
    })));

    setEditingCustomRateAct(null);

    // Persist to DB — update each leg with its share of the total
    finalizeActivityPricesAction(
      allLegIds.map((id, legIdx) => ({
        id,
        contracted_price: unitPrice,
        contracted_total_price: legIdx === 0 ? firstLegTotal : perLegTotal,
      }))
    )
      .then(async (res) => {
        if (res.success && tourId) {
          const posRes = await getPurchaseOrdersAction(tourId);
          if (posRes.success && posRes.pos) setPurchaseOrders(posRes.pos);
        }
      })
      .catch(err => console.error('Rate override persist failed:', err))
      .finally(() => setIsApplyingRateOverride(false));
  };

  const handleResetCustomRateOverride = () => {
    if (!editingCustomRateAct || !tripData) return;
    const dayNum = editingCustomRateAct.tour_itineraries?.day_number || editingCustomRateAct.day_number || editingCustomRateAct.dayNumber || 0;

    setTripData({
      ...tripData,
      accommodations: tripData.accommodations.map(a => {
        if (Number(a.nightIndex) === Number(dayNum)) {
          const { customContractedUnitPrice, customContractedTotalPrice, customRateNote, ...rest } = a as any;
          return rest;
        }
        return a;
      })
    });
    setEditingCustomRateAct(null);
  };

  const handleOpenCustomRateModal = (act: any) => {
    const dayNum = act.tour_itineraries?.day_number || act.day_number || act.dayNumber || 0;
    const acc = tripData?.accommodations?.find(a => Number(a.nightIndex) === Number(dayNum));

    setEditingCustomRateAct(act);
    setCustomRateDriverMeal(act.driver_meal_included || false);
    setCustomRateDriverAcc(act.driver_acc_included || false);
    setCustomRateParking(act.parking_included || false);
    setCustomRateGuideRoomDiscount(act.guide_room_discount || 'None');
    setCustomRateApplyToAllInBlock(false);

    if (acc) {
      setCustomRateUnit(acc.customContractedUnitPrice !== undefined ? String(acc.customContractedUnitPrice) : String(act.contracted_price ?? ''));
      setCustomRateTotal(acc.customContractedTotalPrice !== undefined ? String(acc.customContractedTotalPrice) : String(act.contracted_total_price ?? ''));
      setCustomRateNote(acc.customRateNote || '');
    } else {
      setCustomRateUnit(String(act.contracted_price ?? ''));
      setCustomRateTotal(String(act.contracted_total_price ?? ''));
      setCustomRateNote('');
    }
  };

  const handleOpenHotelDrawer = (act: any) => {
    const dayNum = act.tour_itineraries?.day_number || act.day_number || act.dayNumber || 0;
    let matchingBlock = itinerary.find(b => b.id === act.id) || itinerary.find(b => b.type === ItineraryBlockTypes.SLEEP && Number(b.dayNumber) === Number(dayNum));
    if (!matchingBlock) {
      const hotel = masterData.hotels?.find((h: any) => h.id === act.hotel_id);
      const room = hotel?.hotel_rooms?.find((r: any) => r.id === act.hotel_room_id);
      const newBlock: InternalItineraryBlock = {
        id: act.id || generateUUID(),
        dayNumber: dayNum,
        type: ItineraryBlockTypes.SLEEP,
        name: act.name || 'Overnight Stay',
        hotelId: act.hotel_id || undefined,
        hotelName: hotel?.name || undefined,
        roomName: room?.room_name || undefined,
        mealPlan: act.meal_plan || 'BB',
        startTime: '14:00',
        endTime: '12:00',
        bufferMins: 0,
        durationHours: 22,
        internalNotes: '',
        confirmationStatus: 'Pending',
        paymentStatus: 'Pending'
      };
      setItinerary(prev => [...prev, newBlock]);
      matchingBlock = newBlock;
    }
    if (matchingBlock) {
      setActiveAssignment({ blockId: matchingBlock.id, type: ItineraryBlockTypes.SLEEP });
    }
    setSearchTerm('');
  };

  const handleOpenChangeHotelDrawer = (act: any, stays: any[] = []) => {
    setChangeHotelDrawerAct(act);
    setChangeHotelStays(stays);
    setChangeHotelSelectedHotelId(act.hotel_id || null);

    // Initialize search city with act's location if available
    const hotel = masterData.hotels?.find((h: any) => h.id === act.hotel_id);
    setChangeHotelSearchCity(hotel?.closest_city || act.location_name || '');
    setChangeHotelSearchName('');
    setChangeHotelSearchResults(null);

    // Initialize selectedRooms from tripData accommodations if possible
    const dayNum = act.tour_itineraries?.day_number || act.day_number || act.dayNumber || 0;
    const acc = tripData?.accommodations?.find(a => Number(a.nightIndex) === Number(dayNum));
    if (acc) {
      setChangeHotelSelectedRooms(acc.selectedRooms || []);
    } else {
      setChangeHotelSelectedRooms([]);
    }
    setChangeHotelPendingRoomState({});
    setIsChangeHotelDrawerOpen(true);
  };

  const handleSearchChangeHotels = async () => {
    setChangeHotelIsSearching(true);
    try {
      const res = await searchHotelsAction(changeHotelSearchCity, changeHotelSearchName);
      if (res.success && res.hotels) {
        setChangeHotelSearchResults(res.hotels);
        // Merge into masterData.hotels so details are available
        setMasterData((prev: any) => {
          const existingIds = new Set(prev.hotels.map((h: any) => h.id));
          const newHotels = res.hotels.filter((h: any) => !existingIds.has(h.id));
          return { ...prev, hotels: [...prev.hotels, ...newHotels] };
        });
      } else {
        setChangeHotelSearchResults([]);
      }
    } catch (err) {
      console.error(err);
      setChangeHotelSearchResults([]);
    } finally {
      setChangeHotelIsSearching(false);
    }
  };

  const formatDate = (dateStr: string) => {
    if (!dateStr) return '';
    try {
      const d = new Date(dateStr);
      if (isNaN(d.getTime())) return dateStr;
      return d.toLocaleDateString('en-US', {
        month: 'short',
        day: 'numeric',
        year: 'numeric',
      });
    } catch (e) {
      return dateStr;
    }
  };

  // Share with Tourist email states
  const [shareEmailTo, setShareEmailTo] = useState('');
  const [shareEmailSubject, setShareEmailSubject] = useState('');
  const [shareEmailBody, setShareEmailBody] = useState('');
  const [shareEmailFrom, setShareEmailFrom] = useState('concierge@nilathra.com');
  const [isSendingShareEmail, setIsSendingShareEmail] = useState(false);
  const [shareEmailFeedback, setShareEmailFeedback] = useState<{ type: 'success' | 'error', text: string } | null>(null);
  const [shareTemplateLoaded, setShareTemplateLoaded] = useState<string | null>(null);
  const shareEditorRef = React.useRef<HTMLDivElement>(null);
  const [showShareHtml, setShowShareHtml] = useState(false);
  const [shareEmailAttachments, setShareEmailAttachments] = useState<File[]>([]);
  const [sharedEmails, setSharedEmails] = useState<TourSharedEmail[]>([]);
  const [rfqEmails, setRfqEmails] = useState<TourRfqEmail[]>([]);
  const [rfpEmails, setRfpEmails] = useState<TourRfpEmail[]>([]);
  const [dayToItinIdMap, setDayToItinIdMap] = useState<Record<number, string>>({});
  const [expandedHotelHistory, setExpandedHotelHistory] = useState<Record<string, boolean>>({});
  const [expandedEmailId, setExpandedEmailId] = useState<string | null>(null);

  const formatDateTime = (dateStr: string) => {
    if (!dateStr) return '';
    try {
      const d = new Date(dateStr);
      if (isNaN(d.getTime())) return dateStr;
      return d.toLocaleString('en-US', {
        month: 'short',
        day: 'numeric',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
      });
    } catch (e) {
      return dateStr;
    }
  };


  // Fetch activities and settings from the database
  useEffect(() => {
    async function loadActivitiesAndSettings() {
      try {
        const res = await getActivitiesAction();
        if (res.success && res.data) {
          setActivitiesList(res.data as TouristActivity[]);
        }
      } catch (error) {
        console.error("Failed to load activities from database:", error);
      }

      try {
        const res = await getAppMarkupsAction();
        if (res.success && res.markups) {
          const settings = res.markups as any;
          setAppSettings(settings);
          if (settings[Settings.Activity_Travel_Prep_Time] !== undefined) {
            setActivityTravelPrepTime(Number(settings[Settings.Activity_Travel_Prep_Time]));
          }
          if (settings[Settings.Daily_Activity_Hours_Limit] !== undefined) {
            setDailyActivityHoursLimit(Number(settings[Settings.Daily_Activity_Hours_Limit]));
          }
          if (settings[Settings.Activity_Average_Speed_Km] !== undefined) {
            setActivityAverageSpeedKm(Number(settings[Settings.Activity_Average_Speed_Km]));
          }
        }
      } catch (error) {
        console.error("Failed to load app settings from database:", error);
      }
    }
    loadActivitiesAndSettings();
  }, []);

  const filteredActivities = useMemo(() => {
    return activitiesList.filter(act => {
      const matchesCategory = activityCategoryFilter === 'All' || act.category === activityCategoryFilter;
      if (!activitySearchTerm) return matchesCategory;

      const term = activitySearchTerm.toLowerCase();
      return matchesCategory && (
        act.activity_name.toLowerCase().includes(term) ||
        act.location_name.toLowerCase().includes(term) ||
        act.district.toLowerCase().includes(term) ||
        act.description.toLowerCase().includes(term)
      );
    });
  }, [activitiesList, activitySearchTerm, activityCategoryFilter]);

  const selectedActivities = useMemo(() => {
    return selectedActivityIds
      .map(id => activitiesList.find(act => act.id === id))
      .filter(Boolean) as TouristActivity[];
  }, [selectedActivityIds, activitiesList]);

  const totalInferredDuration = useMemo(() => {
    return selectedActivities.reduce((acc, act) => acc + act.duration_hours + activityTravelPrepTime, 0);
  }, [selectedActivities, activityTravelPrepTime]);

  const activityBudgetStats = useMemo(() => {
    const days = touristData?.preferences?.duration_days || 0;
    const availableHours = days * dailyActivityHoursLimit;
    const remainingHours = availableHours - totalInferredDuration;
    const remainingDays = remainingHours / dailyActivityHoursLimit;
    return {
      days,
      availableHours,
      remainingHours,
      remainingDays
    };
  }, [touristData?.preferences?.duration_days, totalInferredDuration, dailyActivityHoursLimit]);

  const handleAddActivity = (id: number) => {
    if (!selectedActivityIds.includes(id)) {
      setSelectedActivityIds(prev => [...prev, id]);
    }
  };

  const handleRemoveActivity = (id: number) => {
    setSelectedActivityIds(prev => prev.filter(x => x !== id));
  };
  const handleSaveProgress = async () => {
    if (!tourId || tourId === 'draft-tour') {
      alert('This planner is in preview mode and not attached to a definitive Tour yet.');
      return;
    }
    const activeStepsList = track === 'basic' ? basicSteps : finalSteps;
    const activeIdx = track === 'basic' ? activeBasicStepIndex : activeFinalStepIndex;
    const currentStepObj = activeStepsList[activeIdx] || activeStepsList[0];

    if (track === 'basic' && currentStepObj?.id === 'ai-builder' && isLockedByOther) {
      alert(`Cannot save: This itinerary is currently locked by ${lockOwnerName || 'another user'}.`);
      return;
    }

    setIsSaving(true);
    try {
      const res = await saveTouristDataAction(tourId, touristData);
      if (!res.success) {
        throw new Error(res.error || 'Failed to save tourist data');
      }

      // Automatically sync hotelId of activity blocks that are bound to the sleep hotel of the same day
      const syncedItinerary = itinerary.map(b => {
        if (b.type === ItineraryBlockTypes.ACTIVITY && b.hotelId) {
          const sleepBlock = itinerary.find(s => s.dayNumber === b.dayNumber && s.type === ItineraryBlockTypes.SLEEP);
          if (sleepBlock && sleepBlock.hotelId) {
            return { ...b, hotelId: sleepBlock.hotelId };
          } else {
            return { ...b, hotelId: undefined };
          }
        }
        return b;
      });

      // Clean itinerary to ensure it's a completely plain, JSON-serializable structure with no React or circular references
      const cleanItinerary = JSON.parse(JSON.stringify(syncedItinerary));

      if (tripData) {
        const updatedTripData = {
          ...tripData,
          clientName: `${touristData.profile.first_name || ''} ${touristData.profile.last_name || ''}`.trim() || tripData.clientName,
          clientEmail: touristData.profile.email || tripData.clientEmail,
          clientPhone: touristData.profile.phone || tripData.clientPhone,
          clientAddress: touristData.profile.address || tripData.clientAddress,
          clientPassport: touristData.profile.passport_number || tripData.clientPassport,
          itinerary: cleanItinerary,
          manualSingle,
          manualDouble,
          manualTriple,
          manualFamily,
          profile: {
            ...tripData.profile,
            adults: touristData.preferences.adults ?? tripData.profile?.adults ?? 2,
            children: touristData.preferences.children ?? tripData.profile?.children ?? 0,
            infants: touristData.preferences.infants ?? tripData.profile?.infants ?? 0,
            arrivalDate: touristData.preferences.arrival_date || tripData.profile?.arrivalDate || '',
            departureDate: touristData.preferences.departure_date || tripData.profile?.departureDate || '',
            durationDays: touristData.preferences.duration_days ?? tripData.profile?.durationDays ?? 0,
            budgetTotal: touristData.preferences.budget_total ?? tripData.profile?.budgetTotal ?? 0,
            budgetPerPerson: touristData.preferences.budget_per_person ?? tripData.profile?.budgetPerPerson ?? 0,
            travelStyle: (touristData.preferences.travel_style || tripData.profile?.travelStyle || 'Luxury') as TravelStyle,
            departureCountry: touristData.preferences.departure_country || tripData.profile?.departureCountry || '',
            specialConditions: {
              dietary: touristData.preferences.dietary_requirements || tripData.profile?.specialConditions?.dietary || '',
              medical: touristData.preferences.medical_conditions || tripData.profile?.specialConditions?.medical || '',
              accessibility: touristData.preferences.accessibility_requirements || tripData.profile?.specialConditions?.accessibility || '',
              language: touristData.preferences.language_preference || tripData.profile?.specialConditions?.language || 'English',
              occasion: touristData.preferences.special_notes || tripData.profile?.specialConditions?.occasion || '',
            }
          },
          travelers: (touristData.team || []).map(t => ({
            id: t.id,
            fullName: t.full_name,
            passportNumber: t.passport_number,
            nationality: t.nationality,
            dateOfBirth: t.date_of_birth,
            gender: t.gender,
            dietaryPreferences: t.dietary_preferences,
            mealPreference: t.meal_preference,
            roomPreference: t.room_preference,
            sharedWithIds: t.shared_with_ids,
            medicalNotes: t.medical_notes,
          }))
        };
        const tourRes = await saveTourAction(tourId, updatedTripData);
        if (!tourRes.success) {
          throw new Error(tourRes.error || 'Failed to save itinerary');
        }
      }

      // Save daily driver assignments to database
      const driverPayloads = Object.values(dailyDriverAssignments).flat();
      const driverSaveRes = await saveTourDailyDriversAction(tourId, driverPayloads);
      if (!driverSaveRes.success) {
        console.error("Warning: Failed to save tour daily drivers:", driverSaveRes.error);
      }

      // Save daily transport provider assignments to database
      const transportPayloads = Object.values(dailyTransportAssignments).flat();
      const transportSaveRes = await saveTourDailyTransportsAction(tourId, transportPayloads);
      if (!transportSaveRes.success) {
        console.error("Warning: Failed to save tour daily transports:", transportSaveRes.error);
      }

      // Save daily vehicle assignments to database
      const vehiclePayloads = Object.values(dailyVehicleAssignments).flat();
      const vehicleSaveRes = await saveTourDailyVehiclesAction(tourId, vehiclePayloads);
      if (!vehicleSaveRes.success) {
        console.error("Warning: Failed to save tour daily vehicles:", vehicleSaveRes.error);
      }

      // Save concierge assignments to database
      if (selectedTourConcierges) {
        const selectedItems: SaveTourConciergeItemDTO[] = [];
        selectedTourConcierges.forEach((val, key) => {
          if (val.selected) {
            const concItemId = val.concierge_cost_item_id || (key && !key.includes('_') && key.length === 36 ? key : null);
            if (concItemId) {
              selectedItems.push({
                concierge_cost_item_id: concItemId,
                quantity: val.quantity > 0 ? val.quantity : 1,
                cost: val.cost,
                tour_itinerary_id: val.tour_itinerary_id || null
              });
            }
          }
        });
        const conciergeSaveRes = await saveTourConciergesAction(tourId, selectedItems);
        if (!conciergeSaveRes.success) {
          console.error("Warning: Failed to save tour concierges:", conciergeSaveRes.error);
        }
      }

      // Automatically create a draft version snapshot when saving progress
      if (track === 'basic' && currentStepObj?.id === 'ai-builder') {
        const autoLabel = `Auto-saved on ${new Date().toLocaleDateString()} ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`;
        const counts = {
          adults: touristData?.preferences?.adults || 2,
          children: touristData?.preferences?.children || 0,
          infants: touristData?.preferences?.infants || 0,
          single_rooms: manualSingle,
          double_rooms: manualDouble,
          triple_rooms: manualTriple,
          family_rooms: manualFamily
        };
        const draftRes = await saveDraftVersionAction(tourId, cleanItinerary, autoLabel, null, counts);
        if (draftRes.success && draftRes.version) {
          // Update draft versions list
          setDraftVersions(prev => [draftRes.version as DraftItineraryVersion, ...prev]);
        }
      }

      alert('Workflow state, client profile and itinerary saved to database successfully.');
    } catch (error: any) {
      console.error("Failed to save progress detailed error:", error);
      alert("Error saving: " + (error.stack || error.message || String(error)));
    } finally {
      setIsSaving(false);
    }
  };

  const handleLoadVersion = async (version: Omit<DraftItineraryVersion, 'itinerary_data'>) => {
    if (window.confirm(`Are you sure you want to load version ${version.version_number} (${version.label || 'no label'})? Any unsaved edits will be replaced.`)) {
      try {
        const res = await getDraftVersionAction(version.id);
        if (res.success && res.version) {
          setItinerary(sortItineraryChronologically(res.version.itinerary_data || []));

          // Fetch any assigned hotels and restaurants to populate masterData
          const hotelIds = (res.version.itinerary_data || [])
            .filter((b: any) => b.type === ItineraryBlockTypes.SLEEP && b.hotelId)
            .map((b: any) => b.hotelId as string);
          if (hotelIds.length > 0) {
            getAssignedHotelsAction(hotelIds).then(hRes => {
              if (hRes.success && hRes.hotels) {
                setMasterData((prev: any) => {
                  const existingIds = new Set(prev.hotels.map((h: any) => h.id));
                  const newHotels = hRes.hotels.filter((h: any) => !existingIds.has(h.id));
                  return { ...prev, hotels: [...prev.hotels, ...newHotels] };
                });
              }
            });
          }

          const restaurantIds = (res.version.itinerary_data || [])
            .filter((b: any) => b.type === ItineraryBlockTypes.MEAL && b.restaurantId)
            .map((b: any) => b.restaurantId as string);
          if (restaurantIds.length > 0) {
            getAssignedRestaurantsAction(restaurantIds).then(rRes => {
              if (rRes.success && rRes.restaurants) {
                setMasterData((prev: any) => {
                  const existingIds = new Set(prev.restaurants.map((r: any) => r.id));
                  const newRestaurants = rRes.restaurants.filter((r: any) => !existingIds.has(r.id));
                  return { ...prev, restaurants: [...prev.restaurants, ...newRestaurants] };
                });
              }
            });
          }

          // Restore guest counts and room counts from the selected version!
          if (res.version.adults !== undefined && res.version.adults !== null) {
            handlePreferenceChange('adults', res.version.adults);
          }
          if (res.version.children !== undefined && res.version.children !== null) {
            handlePreferenceChange('children', res.version.children);
          }
          if (res.version.infants !== undefined && res.version.infants !== null) {
            handlePreferenceChange('infants', res.version.infants);
          }
          if (res.version.single_rooms !== undefined && res.version.single_rooms !== null) {
            setManualSingle(res.version.single_rooms);
          }
          if (res.version.double_rooms !== undefined && res.version.double_rooms !== null) {
            setManualDouble(res.version.double_rooms);
          }
          if (res.version.triple_rooms !== undefined && res.version.triple_rooms !== null) {
            setManualTriple(res.version.triple_rooms);
          }
          if (res.version.family_rooms !== undefined && res.version.family_rooms !== null) {
            setManualFamily(res.version.family_rooms);
          }
        } else {
          alert("Failed to load version: " + res.error);
        }
      } catch (err: any) {
        alert("Error loading version: " + (err.message || err));
      }
    }
  };

  const handleSaveNewVersion = async (label: string) => {
    try {
      const counts = {
        adults: touristData?.preferences?.adults || 2,
        children: touristData?.preferences?.children || 0,
        infants: touristData?.preferences?.infants || 0,
        single_rooms: manualSingle,
        double_rooms: manualDouble,
        triple_rooms: manualTriple,
        family_rooms: manualFamily
      };
      // Clean itinerary to ensure it's a completely plain, JSON-serializable structure with no React or circular references
      const cleanItinerary = JSON.parse(JSON.stringify(itinerary));
      const res = await saveDraftVersionAction(tourId, cleanItinerary, label, null, counts);
      if (res.success && res.version) {
        setDraftVersions(prev => [res.version as any, ...prev]);
        alert("Draft version snapshot saved successfully!");
        return true;
      } else {
        alert("Failed to save draft version snapshot: " + res.error);
        return false;
      }
    } catch (err: any) {
      alert("Error saving version: " + (err.message || err));
      return false;
    }
  };
