  const handleOpenCreateInvoice = () => {
    const defaultName = touristData?.profile ? `${touristData.profile.first_name || ''} ${touristData.profile.last_name || ''}`.trim() : '';
    const defaultEmail = touristData?.profile?.email || '';
    const defaultPhone = touristData?.profile?.phone || '';
    const defaultAddress = touristData?.profile?.address || '';

    setInvoiceBillingName(defaultName);
    setInvoiceBillingEmail(defaultEmail);
    setInvoiceBillingPhone(defaultPhone);
    setInvoiceBillingAddress(defaultAddress);

    // Resolve travel start date (from tours table, or tourist preferences / itinerary)
    const travelStartDate = (guideRfqDetails?.tour?.start_date ? new Date(guideRfqDetails.tour.start_date).toISOString().split('T')[0] : '')
      || touristData?.preferences?.arrival_date
      || tripData?.profile?.arrivalDate
      || (dbActivities?.[0]?.service_date ? new Date(dbActivities[0].service_date).toISOString().split('T')[0] : '');

    // Default 14 days due date, capped at travel start date
    const d = new Date();
    d.setDate(d.getDate() + 14);
    let targetDueDateStr = d.toISOString().split('T')[0];

    if (travelStartDate && targetDueDateStr > travelStartDate) {
      targetDueDateStr = travelStartDate;
    }

    setInvoiceDueDate(targetDueDateStr);

    setInvoiceDiscountAmount('0.00');
    setInvoiceTaxAmount('0.00');

    // Resolve appropriate bank details based on currency
    const tourCurrency = tripData?.profile?.currency || 'USD';
    let defaultNote = '';
    if (tourCurrency === 'LKR') {
      defaultNote = appSettings?.[Settings.Bank_Details_Lkr] || 'Thank you for booking with Nilathra Collection. Payments can be settled via bank transfer.\n\nBank: Hatton National Bank\nAccount Name: Nilathra Collection Pvt Ltd\nAccount Number: 102030405060\nBranch: Colombo Fort\nSWIFT: HNBCLKX';
    } else {
      defaultNote = appSettings?.[Settings.Bank_Details_Usd] || 'Thank you for booking with Nilathra Collection. Payments can be settled via bank transfer.\n\nBank: Hatton National Bank (USD Account)\nAccount Name: Nilathra Collection Pvt Ltd\nAccount Number: 102030405070\nBranch: Colombo Fort\nSWIFT: HNBCLKX';
    }
    setInvoiceAgencyNote(defaultNote);
    setInvoiceCustomServiceFee('');
    setInvoiceFlightsQuotedSeparately(false);
    setInvoiceFlightsQuotedPrice('0.00');
    setCustomerInvoicePreviewItems([]);

    setShowCreateCustomerInvoiceModal(true);
  };

